<?php $edit=query('SELECT * FROM shipping_methods WHERE id=? AND deleted_at IS NULL',[(int)($_GET['id']??0)])->fetch()?:[];$showDeleted=($_GET['deleted']??'')==='1';?>
<div class="page-title"><div><p class="eyebrow">DOSTAVA I USLOVI</p><h1>Načini dostave</h1><p>Uređujte ponudu dostave i predloške za pripremu pošiljki.</p></div><a class="btn" href="?page=delivery">＋ Novi način dostave</a></div>
<section class="panel"><h2><?=$edit?'Uredi dostavu':'Dodaj dostavu'?></h2><?php startForm('delivery',(int)($edit['id']??0));field('name','Naziv',$edit['name']??'');field('courier_name','Kurirska služba (ako se koristi)',$edit['courier_name']??'','text',false);field('cost','Trošak dostave KM',$edit['cost']??'10.00');selectField('payer','Ko plaća dostavu?',deliveryPayers(),$edit['payer']??'customer');textField('terms','Uslovi dostave / rok / posebne napomene',$edit['terms']??'');?><label><input type="checkbox" name="active" <?=!$edit||$edit['active']?'checked':''?>> Dostupno kupcima</label><p class="field-help">Ako dostavu plaća prodavac, kupcu je dostava 0 KM. Isključeni način može se koristiti interno u pripremi pošiljke. Ranije narudžbe zadržavaju svoje cijene i uslove.</p><button>Spremi dostavu</button></form></section>
<section class="panel"><div class="section-heading"><h2><?=$showDeleted?'Obrisani načini dostave':'Registar dostave'?></h2><a href="?page=delivery<?=$showDeleted?'':'&deleted=1'?>"><?=$showDeleted?'Aktivni registar':'Prikaži obrisane'?></a></div><div class="table-scroll"><table><thead><tr><th>Naziv / kurir</th><th>Trošak</th><th>Uslovi</th><th>Dostupnost</th><th>Radnje</th></tr></thead><tbody><?php foreach(query('SELECT * FROM shipping_methods WHERE deleted_at IS '.($showDeleted?'NOT NULL':'NULL').' ORDER BY id DESC')->fetchAll() as $d):?><tr><td><strong><?=e($d['name'])?></strong><br><?=e($d['courier_name'])?></td><td><?=money((float)$d['cost'])?><br><?=e(deliveryPayers()[$d['payer']])?></td><td><?=nl2br(e($d['terms']))?></td><td><?=$d['deleted_at']?'Obrisano':($d['active']?'Dostupno kupcima':'Samo interna priprema')?></td><td><?php if(!$d['deleted_at']):?><a class="table-action" href="?page=delivery&id=<?=$d['id']?>">Uredi</a><details><summary>Obriši</summary><?php startForm('delivery_delete',(int)$d['id']);field('note','Razlog brisanja');?><p class="field-help">Uklanja se iz novog izbora; historija pošiljki ostaje.</p><button>Potvrdi brisanje</button></form></details><?php else:?><?=e($d['deleted_at'])?><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
